#!/usr/bin/env python3
"""
Almatour Pro-subscription installer (idempotent).
Run from the project root (the folder containing `backend/` and `frontend/`):

    python3 apply_pro.py

Safe to run multiple times. After it finishes, run:
    cd backend && python manage.py makemigrations users && python manage.py migrate
"""
import base64, json, os, sys, io

def root_ok():
    return os.path.isdir('backend') and os.path.isdir('frontend')

def read(p):
    with io.open(p, encoding='utf-8') as f: return f.read()

def write(p, s):
    with io.open(p, 'w', encoding='utf-8') as f: f.write(s)

def ensure(label, cond_done, fn):
    if cond_done():
        print(f"  [skip] {label} (already present)")
        return
    fn()
    print(f"  [done] {label}")

NEW_FILES = {
    'frontend/src/pages/Pro.jsx': "",
    'frontend/src/pages/Pro.css': "",
    'frontend/src/pages/Checkout.jsx': "",
    'frontend/src/pages/Checkout.css': "",
}
PRO_BLOCKS = json.loads(base64.b64decode("").decode('utf-8'))

def main():
    if not root_ok():
        print("ERROR: run this from the project root (must contain backend/ and frontend/).")
        sys.exit(1)

    print("== backend/apps/users/urls.py ==")
    p = 'backend/apps/users/urls.py'
    s = read(p)
    def urls_done(): return 'SubscribeView' in s and "name='subscribe'" in s
    def urls_fix():
        nonlocal s
        if 'SubscribeView' not in s:
            s = s.replace(
                'from apps.users.views import RegisterView, ProfileView',
                'from apps.users.views import RegisterView, ProfileView, SubscribeView', 1)
        if "name='subscribe'" not in s:
            s = s.replace(
                "    path('profile/', ProfileView.as_view(), name='profile'),",
                "    path('profile/', ProfileView.as_view(), name='profile'),\n"
                "    path('subscribe/', SubscribeView.as_view(), name='subscribe'),", 1)
        write(p, s)
    ensure('subscribe route + import', urls_done, urls_fix)

    print("== backend/apps/users/admin.py ==")
    p = 'backend/apps/users/admin.py'
    s = read(p)
    def admin_done(): return 'is_pro' in s
    def admin_fix():
        nonlocal s
        s = s.replace(
            "list_display = ('email', 'username', 'phone', 'is_active', 'is_superuser', 'date_joined')",
            "list_display = ('email', 'username', 'phone', 'is_pro', 'is_active', 'is_superuser', 'date_joined')", 1)
        s = s.replace(
            "list_filter = ('is_active', 'is_superuser')",
            "list_filter = ('is_pro', 'is_active', 'is_superuser')", 1)
        s = s.replace(
            "        (None, {'fields': ('email', 'username', 'phone', 'password')}),\n",
            "        (None, {'fields': ('email', 'username', 'phone', 'password')}),\n"
            "        ('Subscription', {'fields': ('is_pro',)}),\n", 1)
        write(p, s)
    ensure('is_pro in admin', admin_done, admin_fix)

    print("== frontend/src/api/client.js ==")
    p = 'frontend/src/api/client.js'
    s = read(p)
    def client_done(): return 'subscribePro' in s
    def client_fix():
        nonlocal s
        line = "export const updateProfile = (data) => client.patch('/users/profile/', data)"
        s = s.replace(line, line + "\nexport const subscribePro = (data) => client.post('/users/subscribe/', data)", 1)
        write(p, s)
    ensure('subscribePro api fn', client_done, client_fix)

    print("== frontend/src/context/AuthContext.jsx ==")
    p = 'frontend/src/context/AuthContext.jsx'
    s = read(p)
    def auth_done(): return 'refreshUser' in s
    def auth_fix():
        nonlocal s
        block = (
            "    const refreshUser = async () => {\n"
            "        const profile = await getProfile()\n"
            "        setUser(profile.data)\n"
            "        return profile.data\n"
            "    }\n\n"
            "    return (\n"
            "        <AuthContext.Provider value={{ user, loading, loginUser, registerUser, logout, refreshUser }}>"
        )
        target = "    return (\n        <AuthContext.Provider value={{ user, loading, loginUser, registerUser, logout }}>"
        if target in s:
            s = s.replace(target, block, 1)
        else:
            print("    [warn] AuthContext Provider line not found verbatim; edit manually.")
        write(p, s)
    ensure('refreshUser in context', auth_done, auth_fix)

    print("== frontend/src/App.jsx ==")
    p = 'frontend/src/App.jsx'
    s = read(p)
    def app_done(): return "import Pro from './pages/Pro'" in s and 'path="/pro"' in s
    def app_fix():
        nonlocal s
        if "import Pro from './pages/Pro'" not in s:
            s = s.replace("import Profile from './pages/Profile'",
                          "import Profile from './pages/Profile'\nimport Pro from './pages/Pro'\nimport Checkout from './pages/Checkout'", 1)
        if 'path="/pro"' not in s:
            s = s.replace(
                '                    <Route path="/profile" element={<PrivateRoute><Profile /></PrivateRoute>} />',
                '                    <Route path="/profile" element={<PrivateRoute><Profile /></PrivateRoute>} />\n'
                '                    <Route path="/pro" element={<PrivateRoute><Pro /></PrivateRoute>} />\n'
                '                    <Route path="/pro/checkout" element={<PrivateRoute><Checkout /></PrivateRoute>} />', 1)
        write(p, s)
    ensure('Pro/Checkout routes + imports', app_done, app_fix)

    print("== frontend/src/pages/Profile.jsx ==")
    p = 'frontend/src/pages/Profile.jsx'
    s = read(p)
    def prof_done(): return 'pro-badge' in s and 'profile-actions' in s
    def prof_fix():
        nonlocal s
        if "Link } from 'react-router-dom'" not in s and "import { useNavigate } from 'react-router-dom'" in s:
            s = s.replace("import { useNavigate } from 'react-router-dom'",
                          "import { useNavigate, Link } from 'react-router-dom'", 1)
        if 'pro-badge' not in s:
            s = s.replace(
                '                    <p className="profile-email">{user.email}</p>\n                </div>',
                '                    <p className="profile-email">{user.email}</p>\n'
                '                    {user.is_pro && (\n'
                '                        <span className="pro-badge" title={t.pro.title}>\u2605 {t.pro.badge}</span>\n'
                '                    )}\n                </div>', 1)
        if 'profile-actions' not in s:
            s = s.replace(
                '            <button className="btn btn-danger" onClick={handleLogout}>{t.profile.signOut}</button>',
                '            <div className="profile-actions">\n'
                '                <Link to="/pro" className="btn btn-primary pro-cta">\n'
                '                    <span className="pro-cta-star">\u2605</span>\n'
                '                    {user.is_pro ? t.pro.proPlan : t.pro.openButton}\n'
                '                </Link>\n'
                '                <button className="btn btn-danger" onClick={handleLogout}>{t.profile.signOut}</button>\n'
                '            </div>', 1)
        write(p, s)
    ensure('Profile badge + Pro button', prof_done, prof_fix)

    print("== frontend/src/pages/Profile.css ==")
    p = 'frontend/src/pages/Profile.css'
    s = read(p)
    def profcss_done(): return '.pro-badge' in s
    def profcss_fix():
        nonlocal s
        css = (
            "\n.pro-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.35rem;\n"
            "    margin-top: 0.6rem;\n    padding: 0.3rem 0.85rem;\n    border-radius: 999px;\n    font-size: 0.8rem;\n"
            "    font-weight: 700;\n    letter-spacing: 0.04em;\n    color: #1a1205;\n"
            "    background: linear-gradient(135deg, #fbbf24, #f59e0b);\n    box-shadow: 0 4px 14px rgba(245, 158, 11, 0.35);\n}\n\n"
            ".profile-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.85rem;\n    align-items: center;\n}\n\n"
            ".pro-cta {\n    background: linear-gradient(135deg, #f59e0b, #ef8b00);\n    box-shadow: 0 4px 16px rgba(245, 158, 11, 0.35);\n}\n\n"
            ".pro-cta:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 6px 24px rgba(245, 158, 11, 0.45);\n    color: #fff;\n}\n\n"
            ".pro-cta-star {\n    font-size: 1.05rem;\n    line-height: 1;\n}\n"
        )
        write(p, s + css)
    ensure('Profile.css pro styles', profcss_done, profcss_fix)

    print("== new page files ==")
    for rel, data in NEW_FILES.items():
        if os.path.exists(rel):
            print(f"  [skip] {rel} (exists)")
        else:
            write(rel, base64.b64decode(data).decode('utf-8'))
            print(f"  [done] {rel}")

    print("== frontend/src/i18n/translations.jsx ==")
    p = 'frontend/src/i18n/translations.jsx'
    s = read(p)
    if 'buyButton' in s:
        print("  [skip] pro translation blocks (already present)")
    else:
        for anchor, block in PRO_BLOCKS.items():
            needle = "noCalendar: '%s',\n        },\n" % anchor
            if needle in s:
                s = s.replace(needle, needle + block, 1)
                print(f"  [done] pro block for anchor: {anchor[:20]}...")
            else:
                print(f"  [warn] anchor not found, skipped: {anchor[:20]}...")
        write(p, s)

    print("\nAll edits applied. Final step:")
    print("  cd backend && python manage.py makemigrations users && python manage.py migrate")

if __name__ == '__main__':
    main()
